INSERT INTO `services` VALUES (1,'graphics-designing','Graphic Design','services/brush.png','Logos, branding, brochures, posters, packaging, and social media creatives.','We create stunning visual designs that communicate your brand’s message clearly and attractively.','We make your brand visually powerful, consistent and memorable across every touchpoint.','2026-10-21 12:34:09','2026-10-21 12:34:09',NULL),(2,'digital-marketing','Digital Marketing','services/trendingUp.png','Social media management, SEO, lead generation, paid ads and influencer marketing.','Grow your business with data-driven marketing strategies that deliver real, measurable results.','We help you reach the right audience, increase visibility and turn attention into revenue.','2026-10-21 12:34:09','2026-10-21 12:34:09',NULL),(3,'photo-video-shoot','Photo & Video Shoot','services/photoCamera.png','Product shoots, corporate shoots, events, reels, and promo visual content.','High-quality visuals that tell your story and elevate your brand across every platform.','We capture your brand in the best light so your audience instantly connects with your story.','2026-10-21 12:34:09','2026-10-21 12:34:09',NULL),(4,'video-editing','Video Editing','services/videoCam.png','Reels, YouTube videos, corporate films, cinematic editing & motion graphics.','We turn your raw footage into polished, engaging video content that works for marketing and branding.','From timeline to thumbnail, every frame is crafted to hold attention and drive action.','2026-10-21 12:34:09','2026-10-21 12:34:09',NULL),(5,'podcast-studio','Podcast Studio','services/headphones.png','Audio recording, video podcast setup, editing and complete post-production.','Record your podcast with professional sound, studio lighting and a complete production setup.','Perfect for creators, influencers and businesses who want podcasts that look and sound premium.','2026-10-21 12:34:09','2026-10-21 12:34:09',NULL),(6,'voice-artist','Voice Artist & Voice Recording','services/recordVoiceOver.png','Professional voiceovers, narration, dubbing and studio-quality audio recording.','Professional voice solutions that add character, clarity and impact to your content.','From tone to timing, every line is recorded to match your script, audience and brand personality.','2026-10-21 12:34:09','2026-10-21 12:34:09',NULL),(7,'website-development','Web Development','services/web.png','Corporate websites, e-commerce stores, portfolios and business websites.','We build modern, responsive and SEO-friendly websites that represent your brand beautifully.','Your website becomes a powerful growth asset – fast, secure and designed for real users.','2026-10-21 12:34:09','2026-10-21 12:34:09',NULL),(8,'application-development','Application Development','services/mobile.png','Android, iOS and hybrid apps for e-commerce, service & booking businesses.','Smart, functional mobile applications tailored to your business workflows and customer journey.','We turn your ideas into powerful digital tools that your customers love to use.','2026-10-21 12:34:09','2026-10-21 12:34:09',NULL);
